/**
 * Application state helpers for use in scripts and actions.
 *
 * The session ID determines which user's application state is read/written.
 * Resolution order:
 *   1. Per-request context (AsyncLocalStorage) — set by the HTTP handler
 *   2. AGENT_USER_EMAIL env var — CLI scripts only
 *
 * The per-request context is critical in multi-user deployments: the env var
 * is process-global and gets overwritten by concurrent requests, so it cannot
 * reliably identify the caller. Only CLI scripts (single-user, no HTTP
 * context) should fall through to the env var.
 */
import { getAmbientUserEmail, getRequestRunContext, } from "../server/request-context.js";
import { appStateGet, appStatePut, appStateDelete, appStateCompareAndSet, appStateCompareAndSetMany, appStateList, appStateDeleteByPrefix, } from "./store.js";
/**
 * Resolve session ID for the current caller.
 *
 * In an HTTP/action context, uses the per-request user email from
 * AsyncLocalStorage so concurrent users don't collide. In a CLI context
 * (no request), falls back to AGENT_USER_EMAIL. Throws when neither is
 * present — application state must be scoped to a real identity.
 */
async function resolveSessionId() {
    try {
        const { getRequestUserEmail } = await import("../server/request-context.js");
        const ctxEmail = getRequestUserEmail();
        if (ctxEmail)
            return ctxEmail;
    }
    catch {
        // request-context not available — fall through to env var
    }
    const email = getAmbientUserEmail();
    if (email)
        return email;
    throw new Error("Application state access requires an authenticated request context or AGENT_USER_EMAIL env var");
}
export async function readAppState(key) {
    return readUnscopedAppState(requestScopedAppStateKey(key));
}
export async function writeAppState(key, value) {
    const sessionId = await resolveSessionId();
    return appStatePut(sessionId, requestScopedAppStateKey(key), value, {
        requestSource: "agent",
    });
}
export async function deleteAppState(key) {
    const sessionId = await resolveSessionId();
    return appStateDelete(sessionId, requestScopedAppStateKey(key), {
        requestSource: "agent",
    });
}
export async function compareAndSetAppState(key, expectedValue, nextValue) {
    const sessionId = await resolveSessionId();
    return appStateCompareAndSet(sessionId, requestScopedAppStateKey(key), expectedValue, nextValue, { requestSource: "agent" });
}
export async function compareAndSetManyAppState(operations) {
    const sessionId = await resolveSessionId();
    return appStateCompareAndSetMany(sessionId, operations.map((operation) => ({
        ...operation,
        key: requestScopedAppStateKey(operation.key),
    })), { requestSource: "agent" });
}
export async function listAppState(prefix) {
    const sessionId = await resolveSessionId();
    return appStateList(sessionId, prefix);
}
export async function deleteAppStateByPrefix(prefix) {
    const sessionId = await resolveSessionId();
    return appStateDeleteByPrefix(sessionId, prefix, {
        requestSource: "agent",
    });
}
const SAFE_TAB_ID_RE = /^[A-Za-z0-9_-]{1,96}$/;
const TAB_SCOPED_AMBIENT_KEYS = new Set([
    "navigation",
    "navigate",
    "__url__",
    "__set_url__",
]);
/**
 * Exported so server code that reads a browser-tab id off a request header
 * (e.g. action-routes.ts) shares this exact validation instead of a copy —
 * only a tab-id-shaped value is ever trusted to scope app state.
 */
export function normalizeBrowserTabId(value) {
    if (typeof value !== "string")
        return null;
    const trimmed = value.trim();
    return SAFE_TAB_ID_RE.test(trimmed) ? trimmed : null;
}
/**
 * Browser tab id for the current request, if the client sent one. Used to
 * scope ambient navigation state so a chat from one tab
 * reads that tab's state instead of whichever tab wrote the global key last.
 */
export function getCurrentRequestBrowserTabId() {
    try {
        return normalizeBrowserTabId(getRequestRunContext()?.browserTabId);
    }
    catch {
        return null;
    }
}
/** `key:<tabId>` when a browser tab id is present, otherwise `key`. */
export function appStateKeyForBrowserTab(key, browserTabId) {
    const normalized = normalizeBrowserTabId(browserTabId);
    return normalized ? `${key}:${normalized}` : key;
}
function requestScopedAppStateKey(key) {
    if (!TAB_SCOPED_AMBIENT_KEYS.has(key))
        return key;
    return appStateKeyForBrowserTab(key, getCurrentRequestBrowserTabId());
}
async function readUnscopedAppState(key) {
    const sessionId = await resolveSessionId();
    return appStateGet(sessionId, key);
}
/**
 * Read application state scoped to the requesting browser tab. Reads the
 * tab-scoped key first. Global fallback is opt-in when a browser tab is
 * present, so a missing tab snapshot cannot silently expose another tab.
 */
export async function readAppStateForCurrentTab(key, options) {
    const browserTabId = getCurrentRequestBrowserTabId();
    const tabKey = appStateKeyForBrowserTab(key, browserTabId);
    if (tabKey !== key) {
        const scoped = await readAppState(tabKey);
        if (scoped)
            return scoped;
        if (options?.fallbackToGlobal !== true)
            return null;
    }
    return readUnscopedAppState(key);
}
/** Write application state scoped to the requesting browser tab. */
export async function writeAppStateForCurrentTab(key, value) {
    const tabKey = appStateKeyForBrowserTab(key, getCurrentRequestBrowserTabId());
    return writeAppState(tabKey, value);
}
